DELETE FROM session_store.spring_session_attributes WHERE session_primary_id IN (
    SELECT primary_id FROM session_store.spring_session WHERE session_id = #{sessionId} FOR UPDATE
)

DELETE FROM session_store.spring_session_attributes WHERE session_primary_id IN (
    SELECT primary_id FROM session_store.spring_session WHERE principal_name = CAST(#{userId} AS TEXT) FOR UPDATE
)
